<script setup lang="ts">
import {computed,onBeforeUnmount,ref} from 'vue'
import PlayTable from '../play/App.vue'
import {createRoomClient} from './client'
import {currentAccount} from '../account/client'
import '../menu/menu.css'
import {avatarUrl} from '../account/contracts'
const client=createRoomClient(),{room,connected,busy,notice,showMatchResults}=client
const nickname=computed(()=>currentAccount.value?.nickname??'玩家'),code=ref(new URLSearchParams(location.search).get('room')??'')
const chosenRounds=ref(8)
async function create(){await client.create(nickname.value);if(room.value&&chosenRounds.value!==room.value.totalRounds)await client.command('configure-match',{totalRounds:chosenRounds.value})}
async function returnMenu(confirmed=false){if(room.value&&!finished.value){if(!confirmed&&!confirm(room.value.match?'返回主菜单将暂离并托管，席位与积分保留。是否继续？':'离开当前房间并返回主菜单？'))return;if(!await client.command('leave'))return}location.href='?scene=menu'}
async function copyRoom(){try{await navigator.clipboard.writeText(room.value?.roomCode??'');notice.value='房间号已复制。'}catch{notice.value='复制不可用，请手动记下房间号。'}}
const startHint=computed(()=>{if(!room.value)return '';const missing=room.value.seats.filter(p=>!p).length;if(missing)return `还差${missing}位牌友，等待加入或补齐机器人。`;const waiting=room.value.seats.filter((p,i)=>p&&!p.bot&&i!==room.value!.hostSeat&&(!p.connected||!p.ready));if(waiting.length)return `等待${waiting.map(p=>p!.nickname).join('、')}准备。`;return room.value.canStart?'牌友已就绪，房主可以开始游戏。':'至少需要两名真人在线。'})
const isHost=computed(()=>room.value?.selfSeat===room.value?.hostSeat)
const names=computed(()=>room.value?.seats.map(p=>p?.nickname??'空位')??[])
const avatars=computed(()=>room.value?.seats.map(p=>avatarUrl(p?.avatar??'lotus'))??[])
const finished=computed(()=>!!room.value?.match&&room.value.match.state!=='active')
const showFinal=computed(()=>finished.value&&(showMatchResults.value||!room.value?.game))
const ownerAway=computed(()=>{const m=room.value?.match;return m&&!room.value?.seats[m.ownerSeat]?.connected})
async function endMatch(){if(confirm('提前结束本场？仅累计已结算局，结果会标记未打满。'))await client.command('end-request')}
async function newMatch(){if(confirm('再开一场将清零本场积分，是否继续？')){if(await client.command('new-match'))showMatchResults.value=false}}
onBeforeUnmount(()=>client.close())
</script>
<template>
  <main v-if="showFinal&&room?.match" class="network-lobby menu-surface final-room has-room"><section class="lobby-card match-summary menu-panel"><h1>{{room.match.state==='early'?'提前结束 · 未打满':'整场结束'}}</h1><p class="match-progress">已完成 {{room.match.completed}}／{{room.match.totalRounds}} 局</p><div class="match-summary-body"><ol aria-label="本场最终排名"><li v-for="r in room.match.ranking" :key="r.seat">第{{r.rank}}名 · {{room.seats[r.seat]?.nickname??room.match.members[r.seat].nickname}}：{{r.score}}分</li></ol><div class="match-ledger" role="region" aria-label="逐局积分明细" tabindex="0"><table><caption>逐局积分 · 可滚动查看</caption><thead><tr><th>局</th><th v-for="p in room.match.members" :key="p.id">{{p.nickname}}</th></tr></thead><tbody><tr v-for="(e,i) in room.match.entries" :key="e.eventId"><td>{{i+1}}{{e.draw?'（流局）':''}}</td><td v-for="(d,j) in e.deltas" :key="j">{{d>0?'+':''}}{{d}}</td></tr></tbody></table></div></div><footer class="match-summary-footer"><div class="match-summary-actions"><button v-if="room.game" @click="showMatchResults=false">查看本局牌桌</button><button v-if="isHost" :disabled="busy||!connected" @click="newMatch">再开一场</button><button :disabled="busy" @click="client.command('leave')">离开房间</button></div><p>当前只保留本场结果，服务重启后房间失效。</p></footer></section></main>
  <template v-else-if="room?.game">
    <PlayTable @exit="returnMenu(true)" :remote-session="client.table" :remote-room-code="room.roomCode" :remote-can-continue="(isHost||finished) && connected && !busy" :remote-names="names" :remote-avatars="avatars" :remote-total-rounds="room.totalRounds"><template #network-actions><div v-if="room.game.view.result" class="match-controls-inline"><button v-if="finished" @click="showMatchResults=true">查看整场结果</button><button v-else-if="room.selfSeat===room.match?.ownerSeat||ownerAway" :disabled="busy||!connected" @click="endMatch">{{ownerAway?'申请提前结束':'提前结束本场'}}</button><template v-if="room.match?.vote"><span>提前结束申请：需全部在线玩家同意（有人重连／离线则取消申请）。</span><template v-if="!room.match.vote.agreed.includes(room.selfSeat)"><button @click="client.command('end-vote',{voteId:room.match.vote.id,agree:true})">同意提前结束</button><button @click="client.command('end-vote',{voteId:room.match.vote.id,agree:false})">不同意</button></template></template></div></template></PlayTable>
    <div class="room-connection" role="status" :title="notice" :aria-label="notice">房间 {{room.roomCode}} · {{isHost?'房主':'玩家'}} · {{connected?'已连接':'连接中断'}}<button v-if="connected&&!finished" @click="client.command('leave')">暂离并托管</button></div>
    <div v-if="!connected" class="connection-cover"><p>{{notice}}</p><small>恢复后同步服务端当前牌局，离线时不能操作。</small><button :disabled="busy" @click="client.retry()">重新连接／返回入口</button></div>
  </template>
  <main v-else class="network-lobby menu-surface" :class="{'has-room':!!room}" data-scene="online" :data-connected="connected" :data-room-code="room?.roomCode??''" :data-seat="room?.selfSeat??-1">
    <header class="menu-top"><button @click="returnMenu()">‹ 返回主菜单</button><span>已登录：{{nickname}}</span></header>
    <img class="menu-title-small" src="/menu/title.png" alt="红中痞子杠"/>
    <section class="lobby-card menu-panel">
      <h1 v-if="!room">联机模式</h1><p role="status" class="menu-notice">{{notice}}</p><div v-if="!room||!connected" class="connection-actions"><button :disabled="connected||busy" @click="client.retry()">重新连接</button><button v-if="!room" :disabled="!connected||busy" title="找回当前账号保留的席位与本场积分" @click="client.retry()">恢复本场</button></div>
      <template v-if="!room"><p class="muted">约上熟悉的牌友，围桌打一场。房间最多四人，支持4／8局。</p>
        <div class="room-entry"><section><h2>创建房间</h2><p class="muted">做一回东道主，邀请好友入座。</p><label>整场局数<select aria-label="创建整场局数" v-model.number="chosenRounds"><option :value="4">4局</option><option :value="8">8局</option></select></label><button class="gold-button" :disabled="!connected||busy" @click="create">创建房间</button></section>
        <section><h2>加入房间</h2><p class="muted">输入好友的房间号，马上入座。</p><label>六位房间号<input v-model="code" aria-label="房间号" inputmode="numeric" maxlength="6" placeholder="请输入六位房间号" /></label><button :disabled="!connected||busy||!/^\d{6}$/.test(code)" @click="client.join(nickname,code)">加入房间</button></section></div>
        
      </template>
      <template v-else>
        <div class="room-heading"><h2>房间 {{room.roomCode}}</h2><button aria-label="复制房间号" @click="copyRoom">复制房间号</button></div>
        <p class="muted">你是{{room.selfSeat+1}}号座位{{isHost?' · 房主':''}} · {{room.totalRounds}}局朋友场</p>
        <label v-if="!room.match">整场局数<select aria-label="整场局数" :value="room.totalRounds" :disabled="!isHost||busy" @change="client.command('configure-match',{totalRounds:Number(($event.target as HTMLSelectElement).value)})"><option :value="4">4局</option><option :value="8">8局</option></select></label>
        <ol class="room-seats"><li v-for="(p,i) in room.seats" :key="i" :class="{'empty-seat':!p}"><span class="seat-number">{{i+1}}号座位</span><img v-if="p" :src="avatarUrl(p.avatar)" :alt="`${p.nickname}头像`"/><div v-else class="empty-avatar" aria-hidden="true">＋</div><strong>{{p?.nickname??'虚位以待'}}</strong><span v-if="p" class="seat-status">{{room.hostSeat===i?'房主':p.bot?'电脑牌友':p.connected?(p.ready?'已准备':'未准备'):'离线保席'}}</span><span v-else class="seat-status">等待好友加入</span></li></ol>
        <p class="start-hint">{{startHint}}</p><div class="menu-actions"><button v-if="!isHost" class="gold-button" :disabled="busy||!connected" @click="client.command('ready',{ready:!room.seats[room.selfSeat]?.ready})">{{room.seats[room.selfSeat]?.ready?'取消准备':'准备'}}</button><button v-if="isHost" class="gold-button" :disabled="busy||!connected||!room.canStart" @click="client.command('start')">开始游戏</button><button :disabled="busy||!connected" @click="client.command('leave')">{{room.match?'暂离并托管':'离开房间'}}</button></div>
        <details v-if="isHost&&!room.match" class="local-tools"><summary>本地调试 · 机器人补位</summary><div class="menu-actions"><button :disabled="busy" @click="client.command('fill-bots')">补齐机器人</button><button :disabled="busy" @click="client.command('remove-bots')">移除机器人</button></div><p class="muted">至少两名真人，空位可用机器人补齐。开场后成员固定。</p></details>
        <p class="muted">首局其他三席准备后由房主开始；同一整场局间点击继续即可进入下一局。</p>
      </template>
    </section>
  </main>
</template>
<style scoped>
.room-connection button{pointer-events:auto;padding:4px 7px;margin:0 0 0 6px;font-size:11px}.match-summary ol{list-style:none;padding:0}.match-summary li{margin:8px 0}.match-controls{position:fixed;right:16px;top:56px;z-index:310;max-width:320px;background:#123126;padding:8px;border:1px solid #b99b53;border-radius:8px}.match-summary table{width:100%;border-collapse:collapse}.match-summary td,.match-summary th{padding:6px;border:1px solid #7f9479}.network-lobby:not(.menu-surface){height:100dvh;overflow:auto;background:#071c14;display:grid;place-items:start center;padding:20px;color:#f8f3df}.lobby-card:not(.menu-panel){width:min(100%,520px);padding:24px;border:1px solid #b99b53;border-radius:12px;background:#123126}h1{font-size:24px;margin:0 0 12px}h2{font-size:20px}label{display:block;margin:14px 0 6px}input{display:block;width:100%;box-sizing:border-box;margin-top:6px;padding:10px;border-radius:6px;background:#0b2019;color:#fff;border:1px solid #7f9479}button{margin:6px 8px 6px 0;padding:10px 14px;border-radius:8px;border:1px solid #b99b53;background:#aa8234;color:#fff;cursor:pointer}button:disabled{opacity:.45;cursor:default}.room-seats{display:block;padding-left:0;list-style:none}.room-seats li{display:block;margin:12px 0}.lobby-note{font-size:12px;line-height:1.6;color:#b4c4b7}a{color:#e6c983}.room-connection{position:fixed;left:8px;top:32px;z-index:80;max-width:60vw;white-space:nowrap;font-size:11px;padding:3px 5px;background:#0a211bcc;color:#f8f3df;pointer-events:none}.connection-cover{position:fixed;inset:44px 0 0;z-index:300;display:flex;flex-direction:column;align-items:center;justify-content:center;background:#071c14d9;color:#fff;text-align:center;padding:20px}
</style>

