.menu-surface.network-lobby{display:block}.menu-panel.lobby-card{max-width:900px}.room-entry{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin-top:24px}.room-entry>section{padding:22px;background:#071f1b88;border:1px solid #d3b06d55;border-radius:14px}.room-entry label{margin:16px 0}.room-entry button{width:100%;margin-top:12px}.room-heading{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.room-heading h2{color:#ffe6a7;font-size:28px}.menu-surface .room-seats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;padding:0;margin:24px 0}.menu-surface .room-seats li{display:flex;align-items:center;flex-direction:column;gap:10px;min-width:0;padding:18px 8px;border:1px solid #d5b46b88;border-radius:14px;background:linear-gradient(#235a49b3,#0b291fe6);margin:0}.room-seats img,.empty-avatar{width:72px;height:72px;border:2px solid #d6b573;border-radius:50%;object-fit:cover}.empty-avatar{display:grid;place-items:center;font-size:34px;color:#d3be8d;background:#ffffff08}.room-seats strong{max-width:100%;overflow-wrap:anywhere;text-align:center;font-size:16px}.seat-number{font-size:12px;color:#bdcbbb}.seat-status{font-size:13px;color:#ffe3a4}.empty-seat{opacity:.65}.start-hint{padding:12px 16px;border-radius:10px;background:#dfb76412;border:1px solid #d4ac6133;color:#ffe5a7}.local-tools{margin:24px 0 12px;border-top:1px solid #d4ac6133;padding-top:16px;font-size:13px}.local-tools summary{cursor:pointer;padding:8px;color:#c5d1ba}.menu-surface .muted{color:#c4cfbc}.menu-surface input,.menu-surface select{width:100%}@media(max-width:600px){.room-entry{grid-template-columns:1fr;gap:16px}.room-entry>section{padding:18px}.menu-surface .room-seats{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.room-seats img,.empty-avatar{width:60px;height:60px}.menu-top>span{max-width:48%;overflow-wrap:anywhere;font-size:13px}}
</style>

