.menu-actions button{margin:0;min-height:44px;padding:8px 14px}.has-room .local-tools{position:absolute;right:16px;bottom:10px;margin:0;padding:0;border:0;max-width:48%}.has-room .local-tools summary{min-height:44px;display:flex;align-items:center;padding:8px}.has-room .local-tools[open]{position:relative;max-width:100%;right:auto;bottom:auto}.has-room .lobby-card>p.muted:last-child{display:none}}
